179	// Sends one frame on a fresh connection and collects exactly what the server writes in answer: a
180	// ping sent once the first answer frame arrives is a barrier, so nothing after the pong belongs
181	// to the answer and nothing the server wrote before it is missed.
182	const answerTo = async (
183	  base: string,
184	  request: Record<string, unknown>
185	): Promise<{client: WebSocket; connected?: Frame; frames: Frame[]; sessionId: string}> => {
186	  const client = open(base);
187	  const frames: Frame[] = [];
