189	  let sessionId = '';
190	  let phase: 'opening' | 'asking' | 'answering' = 'opening';
191	  await new Promise<void>(resolve => {
192	    client.on('message', raw => {
193	      const frame = JSON.parse(String(raw)) as Frame;
194	      if (frame.type === 'pong') {
195	        resolve();
196	        return;
197	      }
198	      if (frame.type === 'connected') {
199	        connected = frame;
200	        sessionId = frame.sessionId ?? '';
201	        phase = 'asking';
202	        client.send(JSON.stringify(request));
203	        return;
204	      }
